import{_ as t,o,c as a,ag as s}from"./chunks/framework.Pp2klvcf.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/evolution/polyrepo.md","filePath":"en/evolution/polyrepo.md","lastUpdated":1788681727000}'),i={name:"en/evolution/polyrepo.md"};function n(r,e,p,l,c,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Fast-Vue3 maintains two parallel branches. <code>polyrepo</code> is a single Vue application with build-time UI selection. <code>main</code> is a pnpm/Turbo workspace with independent admin and portal applications.</p><p>Application logic follows Views → Store → API → HTTP. config/ui.ts provides a shared UI registry; Vite aliases select setup, theme provider, login form and showcase modules. The all mode composes seven showcases and uses Element Plus for login.</p><p>The application owns --fv-* design tokens and responsive layout. Ant Design/Naive/iDux use theme providers; Element Plus/Arco/TDesign use their theme selectors; DevUI uses its theme service. This keeps application styling independent of library resets.</p><p>Run pnpm check and build the selected UI mode. Also check desktop/mobile, light/dark and keyboard interaction. Mock only runs in development at /api/user/*.</p><p><a href="/fast-vue3-site/en/guide/getting-started">Choose a branch</a></p>',6)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
